INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000155',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss Austria in German","Use Österreich vocabulary","Talk about Austrian culture and differences"],"explanation":{"intro":"Austria vocabulary at B1 covers the country''s culture, geography, politics, and its relationship with Germany.","culturalNote":"Österreich (Austria) is a German-speaking neighbour with its own distinct identity. Wien (Vienna) is the capital. Austrians speak Austrian German (Österreichisches Deutsch) with different vocabulary (e.g. Jause for snack, Paradeiser for tomato). Famous Austrians: Mozart, Freud, Klimt, Falco. Austria is neutral (Neutralitätsstatus since 1955) and not in NATO."},"examples":[{"german":"Österreich und Deutschland teilen eine Sprache, aber unterscheiden sich in vielen Dialekten und Traditionen.","english":"Austria and Germany share a language but differ in many dialects and traditions."},{"german":"Wiens Kaffeehauskultur ist seit 2011 UNESCO-Weltkulturerbe.","english":"Vienna''s coffee house culture has been UNESCO world cultural heritage since 2011."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss Austrian culture, geography, and its relationship with Germany and German."}}',
'{"items":[{"word":"teilen","translation":"to share","pronunciation":"TY-len","example":"Eine Sprache teilen."},{"word":"sich unterscheiden","translation":"to differ","pronunciation":"zikh OON-ter-shy-den","example":"Sich unterscheiden von."},{"word":"das Weltkulturerbe","translation":"world cultural heritage","pronunciation":"dahs VELT-kool-toor-er-beh","example":"UNESCO-Weltkulturerbe."},{"word":"die Jause","translation":"snack (Austrian)","pronunciation":"dee YOW-zeh","example":"Eine Jause machen."},{"word":"das Kaffeehaus","translation":"coffee house","pronunciation":"dahs KAF-fey-hows","example":"Im Kaffeehaus sitzen."},{"word":"neutral","translation":"neutral","pronunciation":"noy-TRAHL","example":"Neutral bleiben."}]}',
'{"title":"Sich unterscheiden von — to differ from","pattern":"sich von + dative unterscheiden (to differ from, be distinct from)","explanation":"Sich unterscheiden von + dative = to differ from, be distinct from. Die Länder unterscheiden sich voneinander = The countries differ from each other. Sich unterscheiden in + dative = to differ in (specific attribute): Sie unterscheiden sich im Stil = They differ in style. Der Unterschied = the difference. Unterschiedlich = different (adjective). Compare: sich abheben von (to stand out from), anders sein als (to be different from — more basic).","examples":[{"sentence":"Österreichisches Deutsch unterscheidet sich vom Standarddeutschen in Aussprache und Vokabular.","translation":"Austrian German differs from Standard German in pronunciation and vocabulary."},{"sentence":"Die beiden Konzepte unterscheiden sich grundlegend voneinander.","translation":"The two concepts differ fundamentally from each other."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Weltkulturerbe'' means?","options":["world cultural heritage","world heritage","cultural legacy","UNESCO heritage"],"correctAnswer":"world cultural heritage"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Austria and Germany share a language but differ in many dialects and traditions.","options":["Österreich und Deutschland teilen eine Sprache, aber unterscheiden sich in vielen Dialekten und Traditionen.","Österreich und Deutschland sprechen Deutsch.","Es gibt Unterschiede zwischen Österreich und Deutschland.","Österreich und Deutschland sind ähnlich."],"correctAnswer":"Österreich und Deutschland teilen eine Sprache, aber unterscheiden sich in vielen Dialekten und Traditionen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die beiden Konzepte unterscheiden sich grundlegend ___.","options":["voneinander","miteinander","untereinander","durcheinander"],"correctAnswer":"voneinander"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Austrian German differs from Standard German in pronunciation and vocabulary","wordBankItems":["Österreichisches","Deutsch","unterscheidet","sich","vom","Standarddeutschen","in","Aussprache","und","Vokabular","."],"correctAnswer":"Österreichisches Deutsch unterscheidet sich vom Standarddeutschen in Aussprache und Vokabular ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Jause'' is what kind of Austrian term?","options":["Austrian word for snack","Austrian word for meal","Austrian word for coffee break","Austrian word for lunch"],"correctAnswer":"Austrian word for snack"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000156',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss Switzerland in German","Use Schweiz vocabulary","Talk about Swiss German and culture"],"explanation":{"intro":"Switzerland vocabulary at B1 covers the multilingual country, Swiss German (Schweizerdeutsch), and Swiss culture.","culturalNote":"Die Schweiz (Switzerland) is multilingual: German (63%), French (23%), Italian (8%), Romansh (1%). Schweizerdeutsch (Swiss German) dialects are very different from Standard German (Hochdeutsch). Switzerland is not in the EU but has bilateral agreements. Known for: Uhren (watches), Schokolade (chocolate), Banken (banks), Skigebiete (ski resorts), and direkte Demokratie (direct democracy with frequent referendums)."},"examples":[{"german":"In der Schweiz wird neben Deutsch auch Französisch, Italienisch und Rätoromanisch gesprochen.","english":"In Switzerland French, Italian and Romansh are also spoken in addition to German."},{"german":"Das Schweizerdeutsch unterscheidet sich so stark vom Hochdeutschen, dass Hochdeutschsprachige es kaum verstehen.","english":"Swiss German differs so strongly from Standard German that Standard German speakers can hardly understand it."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss Switzerland, Swiss German, and Swiss multilingualism in German."}}',
'{"items":[{"word":"mehrsprachig","translation":"multilingual","pronunciation":"MAYR-shprakh-ikh","example":"Eine mehrsprachige Gesellschaft."},{"word":"das Rätoromanisch","translation":"Romansh","pronunciation":"dahs rä-toh-ro-MAHN-ish","example":"Rätoromanisch sprechen."},{"word":"das Hochdeutsch","translation":"Standard German","pronunciation":"dahs HOKH-doytsh","example":"Hochdeutsch sprechen."},{"word":"kaum","translation":"hardly/barely","pronunciation":"kowm","example":"Kaum verstehen."},{"word":"das Skigebiet","translation":"ski resort area","pronunciation":"dahs SHKEE-geh-beet","example":"Im Skigebiet."},{"word":"direkte Demokratie","translation":"direct democracy","pronunciation":"dee-REK-teh deh-mo-krah-TEE","example":"Direkte Demokratie."}]}',
'{"title":"So stark dass — so strongly that (degree clause)","pattern":"so + adjective/adverb + dass + clause (so [degree] that [result])","explanation":"So...dass = so...that (degree → consequence). Das Schweizerdeutsch unterscheidet sich so stark vom Hochdeutschen, dass... = Swiss German differs so strongly from Standard German that... Pattern: so + adjective/adverb...dass + verb-final clause. Also: dermaßen + adjective...dass (to such an extent that — more emphatic). Comma before dass is mandatory. Compare: sodass (so that — written as one word, expressing purpose or result).","examples":[{"sentence":"Es war so kalt, dass wir drinnen blieben.","translation":"It was so cold that we stayed inside."},{"sentence":"Er sprach so schnell, dass ich ihn nicht verstand.","translation":"He spoke so fast that I did not understand him."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Kaum'' means?","options":["hardly/barely","almost not","nearly","scarcely"],"correctAnswer":"hardly/barely"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Swiss German differs so strongly from Standard German that Standard German speakers can hardly understand it.","options":["Das Schweizerdeutsch unterscheidet sich so stark vom Hochdeutschen, dass Hochdeutschsprachige es kaum verstehen.","Schweizerdeutsch ist anders als Hochdeutsch.","Viele verstehen Schweizerdeutsch nicht.","Hochdeutsch und Schweizerdeutsch sind verschieden."],"correctAnswer":"Das Schweizerdeutsch unterscheidet sich so stark vom Hochdeutschen, dass Hochdeutschsprachige es kaum verstehen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Es war so kalt, dass wir drinnen ___.","options":["blieben","bleiben","geblieben sind","zu bleiben"],"correctAnswer":"blieben"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He spoke so fast that I did not understand him","wordBankItems":["Er","sprach","so","schnell",",","dass","ich","ihn","nicht","verstand","."],"correctAnswer":"Er sprach so schnell , dass ich ihn nicht verstand ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Mehrsprachig'' means?","options":["multilingual","bilingual","polyglot","language-rich"],"correctAnswer":"multilingual"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000157',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss DACH countries — Luxemburg and Liechtenstein","Use DACH vocabulary","Understand the German-speaking world"],"explanation":{"intro":"DACH vocabulary covers the full German-speaking world — Germany, Austria, Switzerland, Liechtenstein, and Luxembourg.","culturalNote":"DACH stands for Deutschland, Österreich (A=Austria), Schweiz (CH=Confoederatio Helvetica). Liechtenstein (between Austria and Switzerland) is the world''s sixth smallest country. Luxemburg is officially trilingual (Luxemburgisch, Français, Deutsch) and the richest EU country per capita. Together the German-speaking countries have about 100 million speakers."},"examples":[{"german":"Der deutschsprachige Raum umfasst mehrere souveräne Staaten mit eigenen Identitäten.","english":"The German-speaking area encompasses several sovereign states with their own identities."},{"german":"Liechtenstein ist eines der wenigen Länder der Welt, das von zwei Binnenstaaten umgeben ist.","english":"Liechtenstein is one of the few countries in the world surrounded by two landlocked states."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss the German-speaking world (DACH) and its countries in German."}}',
'{"items":[{"word":"umfassen","translation":"to encompass/comprise","pronunciation":"OOM-fas-en","example":"Mehrere Länder umfassen."},{"word":"souverän","translation":"sovereign","pronunciation":"zoo-veh-RÄN","example":"Souveräner Staat."},{"word":"der Binnenstaat","translation":"landlocked state","pronunciation":"dayr BIN-en-shtaht","example":"Ein Binnenstaat."},{"word":"umgeben von","translation":"surrounded by","pronunciation":"oom-GAY-ben fon","example":"Umgeben von Bergen."},{"word":"der deutschsprachige Raum","translation":"German-speaking area","pronunciation":"dayr DOYTSH-shprakh-ee-geh rowm","example":"Deutschsprachiger Raum."},{"word":"pro Kopf","translation":"per capita/per head","pronunciation":"proh kopf","example":"Pro Kopf BIP."}]}',
'{"title":"Umgeben von — surrounded by","pattern":"etwas ist von + dative umgeben (something is surrounded by)","explanation":"Umgeben sein von + dative = to be surrounded by. Das Land ist von Bergen umgeben = The country is surrounded by mountains. Passive participle construction. Also: umgeben mit = surrounded with (more figurative: von Freunden umgeben = surrounded by friends). Related: einkreisen (to encircle — military/strategic), einschließen (to enclose — more physical).","examples":[{"sentence":"Die Stadt ist von einem mittelalterlichen Wall umgeben.","translation":"The city is surrounded by a medieval rampart."},{"sentence":"Er ist von seinen Kindern umgeben.","translation":"He is surrounded by his children."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Souverän'' means?","options":["sovereign","independent","autonomous","self-governing"],"correctAnswer":"sovereign"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The German-speaking area encompasses several sovereign states with their own identities.","options":["Der deutschsprachige Raum umfasst mehrere souveräne Staaten mit eigenen Identitäten.","Viele Länder sprechen Deutsch.","Der deutschsprachige Raum ist groß.","Deutschland, Österreich und die Schweiz."],"correctAnswer":"Der deutschsprachige Raum umfasst mehrere souveräne Staaten mit eigenen Identitäten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Stadt ist von einem mittelalterlichen Wall ___.","options":["umgeben","eingeschlossen","umgeben worden","umringt"],"correctAnswer":"umgeben"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He is surrounded by his children","wordBankItems":["Er","ist","von","seinen","Kindern","umgeben","."],"correctAnswer":"Er ist von seinen Kindern umgeben ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Binnenstaat'' means?","options":["landlocked state","inner state","interior country","enclosed country"],"correctAnswer":"landlocked state"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000158',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss German dialects at advanced level","Use Dialekt vocabulary","Talk about regional linguistic variation"],"explanation":{"intro":"Advanced dialect vocabulary covers regional linguistic variation, prestige, and the tension between dialects and Hochdeutsch.","culturalNote":"Germany has hundreds of dialects grouped into Niederdeutsch (Low German, north), Mitteldeutsch (Middle German, centre), and Oberdeutsch (Upper German, south). Famous examples: Bayerisch (Bavarian), Berlinerisch, Kölsch (Cologne), Sächsisch (Saxon). Dialects are markers of regional identity — sometimes stigmatised (Sächsisch), sometimes celebrated (Bayerisch). Plattdeutsch (Low German) is recognised as a regional language."},"examples":[{"german":"Dialekte spiegeln die Geschichte und regionale Identität ihrer Sprecher wider.","english":"Dialects reflect the history and regional identity of their speakers."},{"german":"Im Berufsleben ist Hochdeutsch die erwartete Norm, obwohl Dialekte im Privatleben geschätzt werden.","english":"In professional life Standard German is the expected norm, although dialects are valued in private life."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss German dialects, regional variation, and language prestige in German."}}',
'{"items":[{"word":"widerspiegeln","translation":"to reflect","pronunciation":"VEE-der-shpee-geln","example":"Die Geschichte widerspiegeln."},{"word":"der Sprecher","translation":"speaker","pronunciation":"dayr SHPREKH-er","example":"Dialektsprecher."},{"word":"die Norm","translation":"norm/standard","pronunciation":"dee norm","example":"Die gesellschaftliche Norm."},{"word":"das Prestige","translation":"prestige","pronunciation":"dahs pres-TEE-zheh","example":"Sprachliches Prestige."},{"word":"stigmatisieren","translation":"to stigmatise","pronunciation":"shtig-mah-tee-ZEER-en","example":"Einen Dialekt stigmatisieren."},{"word":"der Regionaldialekt","translation":"regional dialect","pronunciation":"dayr reh-gyoh-NAHL-dee-ah-lekt","example":"Ein Regionaldialekt."}]}',
'{"title":"Widerspiegeln — to reflect (metaphorical)","pattern":"etwas spiegelt etwas wider (separable — to reflect, be a reflection of)","explanation":"Widerspiegeln (separable) = to reflect, mirror (metaphorically). Die Sprache spiegelt die Gesellschaft wider = Language reflects society. Wider (not wieder) — this is the prefix wider- (against, back). Perfect: hat widergespiegelt. Note: sich widerspiegeln in = to be reflected in (reflexive): Die Werte spiegeln sich in der Sprache wider = The values are reflected in the language. Compare: abbilden (to depict — more visual/graphic).","examples":[{"sentence":"Das Ergebnis spiegelt die Stimmung im Land wider.","translation":"The result reflects the mood in the country."},{"sentence":"Die Architektur spiegelt den Zeitgeist der 1970er Jahre wider.","translation":"The architecture reflects the spirit of the 1970s."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Prestige'' means?","options":["prestige","reputation","status","standing"],"correctAnswer":"prestige"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Dialects reflect the history and regional identity of their speakers.","options":["Dialekte spiegeln die Geschichte und regionale Identität ihrer Sprecher wider.","Dialekte zeigen die Herkunft der Sprecher.","Dialekte sind wichtig für Identität.","Regionale Sprache ist Identität."],"correctAnswer":"Dialekte spiegeln die Geschichte und regionale Identität ihrer Sprecher wider."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Ergebnis spiegelt die Stimmung im Land ___.","options":["wider","wieder","ab","aus"],"correctAnswer":"wider"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The architecture reflects the spirit of the 1970s","wordBankItems":["Die","Architektur","spiegelt","den","Zeitgeist","der","1970er","Jahre","wider","."],"correctAnswer":"Die Architektur spiegelt den Zeitgeist der 1970er Jahre wider ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Stigmatisieren'' means?","options":["to stigmatise","to mark","to brand","to label"],"correctAnswer":"to stigmatise"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000159',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss Christmas in German-speaking countries","Use Weihnachten vocabulary","Talk about holiday traditions"],"explanation":{"intro":"Christmas vocabulary at B1 covers the rich German Christmas traditions — the most important cultural holiday.","culturalNote":"Weihnachten (Christmas) is the biggest cultural festival in Germany. Traditions: Adventskalender (advent calendar), Adventskranz (advent wreath), Weihnachtsmarkt (Christmas market — most famously in Nuremberg, Cologne, Dresden), Heiligabend (Christmas Eve, December 24 — when gifts are exchanged), Weihnachtsmann (Father Christmas) or Nikolaus/Christkind. Germany invented the Christmas tree tradition."},"examples":[{"german":"Weihnachtsmärkte verbreiten in der Adventszeit eine festliche Atmosphäre.","english":"Christmas markets spread a festive atmosphere during Advent."},{"german":"In vielen deutschen Familien werden Geschenke am Heiligabend ausgetauscht.","english":"In many German families presents are exchanged on Christmas Eve."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss German Christmas traditions, vocabulary, and cultural practices."}}',
'{"items":[{"word":"die Adventszeit","translation":"Advent season","pronunciation":"dee AD-vents-tsyt","example":"In der Adventszeit."},{"word":"festlich","translation":"festive","pronunciation":"FEST-likh","example":"Festliche Atmosphäre."},{"word":"der Heiligabend","translation":"Christmas Eve","pronunciation":"dayr HY-likh-ah-bent","example":"Am Heiligabend."},{"word":"austauschen","translation":"to exchange","pronunciation":"OWS-tow-shen","example":"Geschenke austauschen."},{"word":"der Adventskranz","translation":"advent wreath","pronunciation":"dayr AD-vents-krants","example":"Den Adventskranz zünden."},{"word":"bescheren","translation":"to give presents (at Christmas)","pronunciation":"beh-SHAY-ren","example":"Die Kinder bescheren."}]}',
'{"title":"Verbreiten — to spread, disseminate","pattern":"etwas verbreitet etwas (something spreads something — news, atmosphere, influence)","explanation":"Verbreiten = to spread, disseminate (transitive). Weihnachtsmärkte verbreiten eine Atmosphäre = Christmas markets spread an atmosphere. Sich verbreiten (reflexive) = to spread (intransitive): Die Nachricht hat sich schnell verbreitet = The news spread quickly. Die Verbreitung = dissemination, spread. Weit verbreitet = widespread, prevalent. Compare: ausbreiten (to spread out — physical extension), verbreiten (to disseminate — content, influence).","examples":[{"sentence":"Das Virus hat sich innerhalb weniger Tage auf mehrere Städte verbreitet.","translation":"The virus spread to several cities within a few days."},{"sentence":"Diese Meinung ist weit verbreitet.","translation":"This opinion is widespread."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Heiligabend'' means?","options":["Christmas Eve","Christmas Night","Holy Evening","Christmas Eve (Dec 24)"],"correctAnswer":"Christmas Eve"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Christmas markets spread a festive atmosphere during Advent.","options":["Weihnachtsmärkte verbreiten in der Adventszeit eine festliche Atmosphäre.","Weihnachtsmärkte sind schön in der Adventszeit.","In Deutschland gibt es Weihnachtsmärkte.","Die Adventszeit ist festlich."],"correctAnswer":"Weihnachtsmärkte verbreiten in der Adventszeit eine festliche Atmosphäre."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Diese Meinung ist weit ___.","options":["verbreitet","verbreitend","zu verbreiten","verbreiten"],"correctAnswer":"verbreitet"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The virus spread to several cities within a few days","wordBankItems":["Das","Virus","hat","sich","innerhalb","weniger","Tage","auf","mehrere","Städte","verbreitet","."],"correctAnswer":"Das Virus hat sich innerhalb weniger Tage auf mehrere Städte verbreitet ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Bescheren'' means?","options":["to give presents at Christmas","to gift","to surprise","to distribute gifts"],"correctAnswer":"to give presents at Christmas"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000015a',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss Carnival/Fasching","Use Karneval vocabulary","Talk about pre-Lent traditions"],"explanation":{"intro":"Karneval/Fasching vocabulary covers Germany''s vibrant pre-Lent carnival traditions.","culturalNote":"Karneval, Fasching, and Fastnacht are the same celebration with regional names. Karneval is used in the Rhineland (Köln, Düsseldorf — Jecken), Fasching in Bavaria and Austria, Fastnacht in southwest Germany. Highlights: Rosenmontag (Rose Monday — major street parade), Weiberfastnacht (Women''s Thursday), Straßenkarnevals in Cologne with millions of participants. Büttenreden (satirical speeches) are traditional."},"examples":[{"german":"Am Rosenmontag ziehen in Köln riesige Karnevalsumzüge durch die Straßen.","english":"On Rose Monday, huge carnival processions pass through the streets of Cologne."},{"german":"Der Kölner Karneval ist für seine Jecken — Karnevalistinnen und Karnevalisten — bekannt.","english":"The Cologne carnival is known for its Jecken — the carnival revellers."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss Karneval, Fasching, and German pre-Lent traditions."}}',
'{"items":[{"word":"der Karnevalsumzug","translation":"carnival procession","pronunciation":"dayr kar-neh-VAHLS-oom-tsoog","example":"Karnevalsumzüge."},{"word":"die Jecken","translation":"carnival revellers (Cologne)","pronunciation":"dee YEK-en","example":"Die Jecken feiern."},{"word":"der Rosenmontagszug","translation":"Rose Monday procession","pronunciation":"dayr ROH-zen-mohn-tahgs-tsoog","example":"Rosenmontagszug."},{"word":"verkleiden","translation":"to dress up/disguise","pronunciation":"fer-KLY-den","example":"Sich verkleiden."},{"word":"der Konfetti","translation":"confetti","pronunciation":"dayr kon-FET-ee","example":"Konfetti werfen."},{"word":"die Büttenfrede","translation":"satirical carnival speech","pronunciation":"dee BÜT-en-ray-deh","example":"Eine Büttenrede halten."}]}',
'{"title":"Durch die Straßen ziehen — to pass/move through the streets","pattern":"durch + accusative ziehen (to pass through, move through — processions, movements)","explanation":"Ziehen durch + accusative = to move through, pass through (processions, rivers, winds). Der Zug zieht durch die Stadt = The procession passes through the city. Strong verb: zieht / zog / ist gezogen (movement = sein). Also: durch + accusative with other movement verbs: gehen (walk through), fahren (drive through), strömen (stream through). Figuratively: ein Geruch zieht durch den Raum = a smell drifts through the room.","examples":[{"sentence":"Die Parade zog durch das Stadtzentrum.","translation":"The parade passed through the city centre."},{"sentence":"Ein kalter Wind zieht durch die Straße.","translation":"A cold wind blows through the street."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Verkleiden'' means?","options":["to dress up/disguise","to costume","to mask","to fancy-dress"],"correctAnswer":"to dress up/disguise"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"On Rose Monday, huge carnival processions pass through the streets of Cologne.","options":["Am Rosenmontag ziehen in Köln riesige Karnevalsumzüge durch die Straßen.","In Köln gibt es am Rosenmontag Karneval.","Köln feiert am Rosenmontag.","Karnevalszüge sind in Köln bekannt."],"correctAnswer":"Am Rosenmontag ziehen in Köln riesige Karnevalsumzüge durch die Straßen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Parade zog durch das ___.","options":["Stadtzentrum","Stadtzentrums","Stadtmitte","Zentrum"],"correctAnswer":"Stadtzentrum"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: A cold wind blows through the street","wordBankItems":["Ein","kalter","Wind","zieht","durch","die","Straße","."],"correctAnswer":"Ein kalter Wind zieht durch die Straße ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Jecken'' are?","options":["Cologne carnival revellers","carnival costumes","jester hats","carnival bands"],"correctAnswer":"Cologne carnival revellers"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000015b',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the Oktoberfest","Use Oktoberfest vocabulary","Talk about Bavarian culture and beer festival"],"explanation":{"intro":"Oktoberfest vocabulary covers the world''s largest folk festival and Bavarian culture.","culturalNote":"Das Oktoberfest (actually mid-September to first October Sunday) in München (Munich) is the world''s largest Volksfest. 6 million visitors annually. The Wiesn (colloquial name) features Bierzelte (beer tents), Trachten (traditional costume — Dirndl for women, Lederhosen for men), Fahrgeschäfte (rides), and Hendl (roast chicken). Each brewery has its own tent. Spezielle Maßkrug = 1 litre beer glass (das Maß)."},"examples":[{"german":"Das Oktoberfest gilt als das weltgrößte Volksfest und zieht Millionen von Besuchern an.","english":"The Oktoberfest is regarded as the world''s largest folk festival and attracts millions of visitors."},{"german":"Wer auf die Wiesn geht, trägt traditionell Tracht — Dirndl oder Lederhosen.","english":"Whoever goes to the Wiesn traditionally wears traditional costume — dirndl or lederhosen."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss the Oktoberfest, Bavarian culture, and German folk festival vocabulary."}}',
'{"items":[{"word":"das Volksfest","translation":"folk festival","pronunciation":"dahs FOLKS-fest","example":"Ein Volksfest."},{"word":"das Bierzelt","translation":"beer tent","pronunciation":"dahs BEER-tselt","example":"Im Bierzelt sitzen."},{"word":"die Tracht","translation":"traditional costume","pronunciation":"dee trakht","example":"Tracht tragen."},{"word":"das Dirndl","translation":"dirndl (Bavarian dress)","pronunciation":"dahs DIRN-dl","example":"Ein Dirndl tragen."},{"word":"die Lederhosen","translation":"lederhosen","pronunciation":"dee LAY-der-hoh-zen","example":"Lederhosen anziehen."},{"word":"das Maß","translation":"one-litre beer glass","pronunciation":"dahs mahs","example":"Ein Maß Bier."}]}',
'{"title":"Wer ... geht / Whoever — generalising relative pronouns","pattern":"wer + verb... (whoever does X — generalising subject)","explanation":"Wer = whoever (generalising — no specific antecedent). Wer auf die Wiesn geht, trägt Tracht = Whoever goes to the Wiesn wears traditional costume. The Wer-clause is the subject; the main clause follows without a pronoun (subject already filled by wer). Compare: derjenige, der (the one who — specific with demonstrative). Was = whatever (for objects). Both use verb-second in the main clause after the wer/was clause.","examples":[{"sentence":"Wer früh kommt, mahlt zuerst (Sprichwort).","translation":"Whoever comes early grinds first (proverb = the early bird gets the worm)."},{"sentence":"Wer nicht wagt, der nicht gewinnt.","translation":"Nothing ventured, nothing gained (lit: whoever doesn''t dare doesn''t win)."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Volksfest'' means?","options":["folk festival","public festival","people''s celebration","carnival"],"correctAnswer":"folk festival"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The Oktoberfest is regarded as the world''s largest folk festival and attracts millions of visitors.","options":["Das Oktoberfest gilt als das weltgrößte Volksfest und zieht Millionen von Besuchern an.","Das Oktoberfest ist sehr groß.","Millionen besuchen das Oktoberfest.","Das Oktoberfest ist bekannt."],"correctAnswer":"Das Oktoberfest gilt als das weltgrößte Volksfest und zieht Millionen von Besuchern an."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Wer früh kommt, mahlt ___.","options":["zuerst","zuerst mal","als erstes","erst"],"correctAnswer":"zuerst"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Whoever goes to the Wiesn traditionally wears traditional costume","wordBankItems":["Wer","auf","die","Wiesn","geht",",","trägt","traditionell","Tracht","."],"correctAnswer":"Wer auf die Wiesn geht , trägt traditionell Tracht ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Maß'' at the Oktoberfest is?","options":["1-litre beer glass","beer stein","festival mug","large beer"],"correctAnswer":"1-litre beer glass"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000015c',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss Easter in Germany","Use Ostern vocabulary","Talk about Easter traditions"],"explanation":{"intro":"Easter vocabulary covers German Easter traditions, symbols, and the role of Ostern in German culture.","culturalNote":"Ostern (Easter) is a major German holiday. Good Friday (Karfreitag) and Easter Monday (Ostermontag) are public holidays. Traditions: Ostereier bemalen (decorating eggs), Osternest (Easter nest — hidden basket), Osterhasen (Easter bunnies), Ostereiersuchen (egg hunt). In Germany, decorated Osterbrunnen (Easter fountains, especially in Franconia) are a tourist attraction. Easter markets are smaller than Christmas ones."},"examples":[{"german":"An Ostern bemalen viele deutsche Familien gemeinsam Eier und suchen nach versteckten Überraschungen.","english":"At Easter, many German families together paint eggs and look for hidden surprises."},{"german":"Der Ostermontag ist in Deutschland ein gesetzlicher Feiertag.","english":"Easter Monday is a statutory public holiday in Germany."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss Easter traditions, vocabulary, and cultural practices in Germany."}}',
'{"items":[{"word":"bemalen","translation":"to paint/decorate","pronunciation":"beh-MAH-len","example":"Eier bemalen."},{"word":"versteckt","translation":"hidden","pronunciation":"fer-SHTEKT","example":"Versteckte Eier."},{"word":"die Überraschung","translation":"surprise","pronunciation":"dee ü-ber-RAH-shoong","example":"Eine Überraschung."},{"word":"der gesetzliche Feiertag","translation":"statutory public holiday","pronunciation":"dayr geh-ZETS-likh-eh FY-er-tahg","example":"Gesetzlicher Feiertag."},{"word":"das Osterei","translation":"Easter egg","pronunciation":"dahs OS-ter-eye","example":"Ostereier suchen."},{"word":"der Osterhase","translation":"Easter bunny","pronunciation":"dayr OS-ter-hah-zeh","example":"Der Osterhase."}]}',
'{"title":"Gemeinsam + verb — together, jointly","pattern":"gemeinsam + verb / gemeinsam etwas tun (to do something together)","explanation":"Gemeinsam = together, jointly, in common. Gemeinsam Eier bemalen = to paint eggs together. Can precede the verb or follow: Wir machen das gemeinsam = We do that together. Etwas gemeinsam haben = to have something in common. Die Gemeinsamkeit = shared quality/common ground. Compare: zusammen (together — more colloquial, physical proximity); gemeinsam (more emphasis on joint effort/shared ownership).","examples":[{"sentence":"Wir haben das Projekt gemeinsam entwickelt.","translation":"We developed the project jointly."},{"sentence":"Was haben diese beiden Länder gemeinsam?","translation":"What do these two countries have in common?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der gesetzliche Feiertag'' means?","options":["statutory public holiday","legal holiday","bank holiday","official holiday"],"correctAnswer":"statutory public holiday"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"At Easter, many German families together paint eggs and look for hidden surprises.","options":["An Ostern bemalen viele deutsche Familien gemeinsam Eier und suchen nach versteckten Überraschungen.","Familien feiern Ostern mit Eiern.","An Ostern suchen Kinder Eier.","Deutsche Familien feiern Ostern zusammen."],"correctAnswer":"An Ostern bemalen viele deutsche Familien gemeinsam Eier und suchen nach versteckten Überraschungen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Wir haben das Projekt ___ entwickelt.","options":["gemeinsam","zusammen","gemeinsamen","miteinander"],"correctAnswer":"gemeinsam"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: What do these two countries have in common?","wordBankItems":["Was","haben","diese","beiden","Länder","gemeinsam","?"],"correctAnswer":"Was haben diese beiden Länder gemeinsam ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Bemalen'' means?","options":["to paint/decorate","to colour","to dye","to mark"],"correctAnswer":"to paint/decorate"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000015d',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss German public holidays","Use Feiertag vocabulary","Know the key German holidays"],"explanation":{"intro":"Public holiday vocabulary covers all German gesetzliche Feiertage and their significance.","culturalNote":"Germany has 9 national holidays (Tag der Deutschen Einheit Oct 3, Neujahr, Karfreitag, Ostermontag, Maifeiertag, Christi Himmelfahrt, Pfingstmontag, Tag der Deutschen Einheit, 1st and 2nd Christmas Day). Plus regional Feiertage: Catholic states (Bavaria, BW) have more. Heilige Drei Könige (Jan 6) is a holiday only in some states. Everything closes — Shops are strictly shut (Ladenschlussgesetz)."},"examples":[{"german":"Am Tag der Deutschen Einheit am 3. Oktober wird die Wiedervereinigung von 1990 gefeiert.","english":"On German Unity Day on 3 October, the reunification of 1990 is celebrated."},{"german":"An gesetzlichen Feiertagen sind in Deutschland alle Geschäfte geschlossen.","english":"On statutory public holidays all shops in Germany are closed."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss German public holidays and their cultural significance."}}',
'{"items":[{"word":"die Wiedervereinigung","translation":"reunification","pronunciation":"dee VEE-der-fer-y-nee-goong","example":"Die Wiedervereinigung 1990."},{"word":"feiern","translation":"to celebrate","pronunciation":"FY-ern","example":"Einen Feiertag feiern."},{"word":"geschlossen","translation":"closed","pronunciation":"geh-SHLOS-en","example":"Geschäfte geschlossen."},{"word":"Christi Himmelfahrt","translation":"Ascension Day","pronunciation":"KRIS-tee HIM-mel-fahrt","example":"Christi Himmelfahrt."},{"word":"Pfingstmontag","translation":"Whit Monday","pronunciation":"PFINGST-mohn-tahg","example":"Pfingstmontag."},{"word":"das Ladenschlussgesetz","translation":"shop closing hours law","pronunciation":"dahs LAH-den-shloos-geh-zets","example":"Ladenschlussgesetz."}]}',
'{"title":"Gefeiert werden — to be celebrated (passive)","pattern":"etwas wird gefeiert (something is celebrated — passive voice)","explanation":"Passive with gefeiert werden = to be celebrated. Der Tag wird gefeiert = The day is celebrated. Die Wiedervereinigung wird gefeiert = Reunification is celebrated. Past passive: wurde gefeiert = was celebrated. Future passive: wird gefeiert werden = will be celebrated. The passive voice is very common in formal descriptions of events, laws, and traditions. Feiertags werden... gefeiert = on holidays... is celebrated.","examples":[{"sentence":"Der Nationalfeiertag wird mit einem Festakt gefeiert.","translation":"The national holiday is celebrated with a formal ceremony."},{"sentence":"Silvester wird in Deutschland mit Feuerwerk gefeiert.","translation":"New Year''s Eve is celebrated in Germany with fireworks."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Wiedervereinigung'' means?","options":["reunification","reuniting","re-union","integration"],"correctAnswer":"reunification"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"On German Unity Day on 3 October, the reunification of 1990 is celebrated.","options":["Am Tag der Deutschen Einheit am 3. Oktober wird die Wiedervereinigung von 1990 gefeiert.","Der 3. Oktober ist ein Feiertag.","Deutschland wurde 1990 vereint.","Der Tag der Deutschen Einheit ist am 3. Oktober."],"correctAnswer":"Am Tag der Deutschen Einheit am 3. Oktober wird die Wiedervereinigung von 1990 gefeiert."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Nationalfeiertag wird mit einem Festakt ___.","options":["gefeiert","gefeiernd","feiern","feiert"],"correctAnswer":"gefeiert"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: New Year''s Eve is celebrated in Germany with fireworks","wordBankItems":["Silvester","wird","in","Deutschland","mit","Feuerwerk","gefeiert","."],"correctAnswer":"Silvester wird in Deutschland mit Feuerwerk gefeiert ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Pfingstmontag'' is?","options":["Whit Monday","Pentecost","Spirit Monday","Trinity Monday"],"correctAnswer":"Whit Monday"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000015e',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss German work culture","Use Arbeitskultur vocabulary","Talk about German workplace values"],"explanation":{"intro":"Work culture vocabulary at B1 covers German workplace values, norms, and expectations.","culturalNote":"Deutsche Arbeitskultur values Pünktlichkeit (punctuality), Gründlichkeit (thoroughness), Zuverlässigkeit (reliability), and Trennung von Arbeit und Privatleben (work-life separation). Siezen (formal address) is still expected in many workplaces. Feierabend (end of work — literally ''celebration evening'') is a cultural concept: when work ends, it ends. Überstundenkultur (overtime culture) is common but controversial."},"examples":[{"german":"In Deutschland wird großen Wert auf Pünktlichkeit und Zuverlässigkeit im Beruf gelegt.","english":"In Germany, great emphasis is placed on punctuality and reliability in the workplace."},{"german":"Das Konzept des Feierabends bedeutet, dass die Arbeit nach Dienstschluss wirklich endet.","english":"The concept of Feierabend means that work truly ends after finishing time."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss German work culture, workplace values, and professional norms."}}',
'{"items":[{"word":"die Zuverlässigkeit","translation":"reliability","pronunciation":"dee tsoo-fer-LÄS-ikh-kyt","example":"Zuverlässigkeit zeigen."},{"word":"die Gründlichkeit","translation":"thoroughness","pronunciation":"dee GRÜND-likh-kyt","example":"Mit Gründlichkeit."},{"word":"der Feierabend","translation":"end of work day","pronunciation":"dayr FY-er-ah-bent","example":"Feierabend machen."},{"word":"der Dienstschluss","translation":"end of working hours","pronunciation":"dayr DEENST-shloos","example":"Nach Dienstschluss."},{"word":"großen Wert legen auf","translation":"to place great emphasis on","pronunciation":"GROH-sen vert LAY-gen owf","example":"Großen Wert legen auf."},{"word":"die Trennung","translation":"separation","pronunciation":"dee TREN-oong","example":"Trennung von Arbeit und Freizeit."}]}',
'{"title":"Großen Wert auf etwas legen — to place great emphasis on","pattern":"(großen) Wert auf + accusative legen (to place (great) value/emphasis on)","explanation":"Wert legen auf + accusative = to place value on, emphasise, prioritise. In Deutschland wird großen Wert auf Qualität gelegt = In Germany great value is placed on quality. Active: Ich lege großen Wert auf Pünktlichkeit = I place great importance on punctuality. Passive: Es wird Wert auf X gelegt = Emphasis is placed on X. Variation: keinen Wert legen auf = not to place value on, not to care about.","examples":[{"sentence":"Das Unternehmen legt großen Wert auf Mitarbeiterzufriedenheit.","translation":"The company places great emphasis on employee satisfaction."},{"sentence":"Sie legt keinen Wert auf formelle Kleidung.","translation":"She doesn''t care about formal clothing."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Feierabend'' means?","options":["end of work day","evening celebration","after-work time","leisure time"],"correctAnswer":"end of work day"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In Germany, great emphasis is placed on punctuality and reliability in the workplace.","options":["In Deutschland wird großen Wert auf Pünktlichkeit und Zuverlässigkeit im Beruf gelegt.","Deutsche sind pünktlich.","Pünktlichkeit ist wichtig in Deutschland.","Im Beruf sind Pünktlichkeit und Zuverlässigkeit wichtig."],"correctAnswer":"In Deutschland wird großen Wert auf Pünktlichkeit und Zuverlässigkeit im Beruf gelegt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Unternehmen legt großen Wert auf Mitarbeiter___.","options":["zufriedenheit","frieden","glück","motivation"],"correctAnswer":"zufriedenheit"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: She doesn''t care about formal clothing","wordBankItems":["Sie","legt","keinen","Wert","auf","formelle","Kleidung","."],"correctAnswer":"Sie legt keinen Wert auf formelle Kleidung ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Gründlichkeit'' means?","options":["thoroughness","precision","carefulness","meticulousness"],"correctAnswer":"thoroughness"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000015f',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss professional networking","Use Networking vocabulary","Talk about career networking in German"],"explanation":{"intro":"Professional networking vocabulary at B1 covers building professional connections in German-speaking environments.","culturalNote":"Networking in Germany is somewhat formal compared to other cultures — cold contact via Xing (German equivalent of LinkedIn) and professional associations (Verbände) is common. Visiting cards (Visitenkarten) are exchanged at conferences. The DACH region uses Xing heavily alongside LinkedIn. Netzwerken as a verb is now accepted in German, despite its anglicism."},"examples":[{"german":"Beim Netzwerken kommt es darauf an, echte Beziehungen aufzubauen, nicht nur Kontakte zu sammeln.","english":"In networking it is important to build genuine relationships, not just collect contacts."},{"german":"Berufsverbände bieten eine gute Möglichkeit, Gleichgesinnte kennenzulernen.","english":"Professional associations offer a good opportunity to get to know like-minded people."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss professional networking and career building in German."}}',
'{"items":[{"word":"es kommt darauf an, zu","translation":"it is important to / it depends on","pronunciation":"es komt dah-ROWF an tsoo","example":"Es kommt darauf an, X zu tun."},{"word":"der Gleichgesinnte","translation":"like-minded person","pronunciation":"dayr GLYKH-geh-zin-teh","example":"Gleichgesinnte treffen."},{"word":"der Berufsverband","translation":"professional association","pronunciation":"dayr beh-ROOFS-fer-bant","example":"Berufsverband beitreten."},{"word":"der Kontakt","translation":"contact","pronunciation":"dayr KON-takt","example":"Kontakte knüpfen."},{"word":"die Visitenkarte","translation":"business card","pronunciation":"dee vee-ZEE-ten-kar-teh","example":"Visitenkarten tauschen."},{"word":"knüpfen","translation":"to build/make (connections)","pronunciation":"KNÜPF-en","example":"Kontakte knüpfen."}]}',
'{"title":"Es kommt darauf an, zu — it is important to / it depends on","pattern":"es kommt darauf an, etwas zu tun (it is important to / it depends on doing)","explanation":"Es kommt darauf an = it depends on / it is important (context determines which). + zu-infinitive: es kommt darauf an, ehrlich zu sein = it is important to be honest. + ob/dass + clause: es kommt darauf an, ob er kommt = it depends on whether he comes. The darauf is an anticipatory da-compound for the following clause or infinitive. Very versatile and common. Compare: ankommen auf + accusative = to matter, depend on (same structure without darauf: Es kommt auf die Qualität an).","examples":[{"sentence":"Es kommt darauf an, wie man mit Stress umgeht.","translation":"It depends on how one deals with stress."},{"sentence":"Es kommt nicht nur auf die Noten an, sondern auch auf die Persönlichkeit.","translation":"It''s not only about the grades, but also about the personality."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Gleichgesinnte'' means?","options":["like-minded person","colleague","ally","fellow"],"correctAnswer":"like-minded person"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In networking it is important to build genuine relationships, not just collect contacts.","options":["Beim Netzwerken kommt es darauf an, echte Beziehungen aufzubauen, nicht nur Kontakte zu sammeln.","Netzwerken bedeutet Kontakte sammeln.","Beim Netzwerken trifft man Leute.","Echte Beziehungen sind wichtig beim Netzwerken."],"correctAnswer":"Beim Netzwerken kommt es darauf an, echte Beziehungen aufzubauen, nicht nur Kontakte zu sammeln."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Es kommt darauf an, wie man mit Stress ___.","options":["umgeht","umgehen","umgehend","umgegangen"],"correctAnswer":"umgeht"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: It''s not only about the grades but also about the personality","wordBankItems":["Es","kommt","nicht","nur","auf","die","Noten","an",",","sondern","auch","auf","die","Persönlichkeit","."],"correctAnswer":"Es kommt nicht nur auf die Noten an , sondern auch auf die Persönlichkeit ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Kontakte knüpfen'' means?","options":["to build/make contacts","to collect contacts","to network","to link contacts"],"correctAnswer":"to build/make contacts"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000160',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss career development","Use Karriere vocabulary","Talk about professional advancement"],"explanation":{"intro":"Career development vocabulary at B1 covers career planning, advancement, and professional goals.","culturalNote":"In Germany, Berufsausbildung (vocational training — apprenticeship system, the Duales Ausbildungssystem) is highly respected alongside university education. Karriereleiter (career ladder), Beförderung (promotion), and Gehaltserhöhung (pay rise) are key career concepts. The culture values Fachkompetenz (professional expertise) over generalist skills."},"examples":[{"german":"Eine kontinuierliche Weiterbildung ist entscheidend für eine erfolgreiche berufliche Karriere.","english":"Continuous further training is decisive for a successful professional career."},{"german":"Viele Unternehmen bieten Mentorenprogramme an, um Nachwuchskräfte zu fördern.","english":"Many companies offer mentoring programmes to promote junior employees."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss career development, professional advancement, and training in German."}}',
'{"items":[{"word":"entscheidend","translation":"decisive/crucial","pronunciation":"ent-SHY-dend","example":"Entscheidend sein."},{"word":"die Nachwuchskraft","translation":"junior employee/talent","pronunciation":"dee NAKH-vooks-kraft","example":"Nachwuchskräfte fördern."},{"word":"das Mentorenprogramm","translation":"mentoring programme","pronunciation":"dahs men-TOH-ren-pro-gram","example":"Mentorenprogramm."},{"word":"die Beförderung","translation":"promotion","pronunciation":"dee beh-FÖR-deh-roong","example":"Eine Beförderung erhalten."},{"word":"die Fachkompetenz","translation":"professional expertise","pronunciation":"dee FAKH-kom-peh-tents","example":"Fachkompetenz zeigen."},{"word":"die Weiterbildung","translation":"further training","pronunciation":"dee VY-ter-bil-doong","example":"Weiterbildungsmaßnahmen."}]}',
'{"title":"Entscheidend für — decisive/crucial for","pattern":"etwas ist entscheidend für + accusative (something is decisive, crucial, key for)","explanation":"Entscheidend = decisive, crucial (participial adjective from entscheiden). Entscheidend für Erfolg = crucial for success. Commonly used in formal evaluation language. Compare: ausschlaggebend (casting vote — very emphatic), wesentlich (essential — broader), wichtig (important — everyday), unerlässlich (indispensable). Die Entscheidung = the decision; entscheidend = decisiveness-related.","examples":[{"sentence":"Die erste Frage war entscheidend für den Ausgang des Spiels.","translation":"The first question was decisive for the outcome of the game."},{"sentence":"Vertrauen ist entscheidend für gute Teamarbeit.","translation":"Trust is crucial for good teamwork."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Nachwuchskraft'' means?","options":["junior employee/talent","new employee","young worker","trainee"],"correctAnswer":"junior employee/talent"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Continuous further training is decisive for a successful professional career.","options":["Eine kontinuierliche Weiterbildung ist entscheidend für eine erfolgreiche berufliche Karriere.","Weiterbildung ist wichtig.","Für eine gute Karriere muss man sich weiterbilden.","Erfolg braucht Weiterbildung."],"correctAnswer":"Eine kontinuierliche Weiterbildung ist entscheidend für eine erfolgreiche berufliche Karriere."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Vertrauen ist entscheidend für gute ___.","options":["Teamarbeit","Teamarbeit sein","Teams","Teamgeist"],"correctAnswer":"Teamarbeit"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The first question was decisive for the outcome of the game","wordBankItems":["Die","erste","Frage","war","entscheidend","für","den","Ausgang","des","Spiels","."],"correctAnswer":"Die erste Frage war entscheidend für den Ausgang des Spiels ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Beförderung'' means?","options":["promotion","advancement","progression","pay rise"],"correctAnswer":"promotion"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000161',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss salary negotiation","Use Gehaltsverhandlung vocabulary","Practice negotiation language"],"explanation":{"intro":"Salary negotiation vocabulary at B1 covers the language of discussing pay, raises, and compensation.","culturalNote":"In Germany, Gehalt (salary) discussions are relatively taboo in social settings but normal in recruitment contexts. The Mindestlohn (minimum wage — introduced 2015, regularly increased) is an important labour policy tool. Tarifvertrag (collective wage agreement) covers many workers. A Gehaltserhöhung (pay rise) can be requested in an annual Mitarbeitergespräch (performance review)."},"examples":[{"german":"Bei Gehaltsverhandlungen ist es wichtig, gut informiert über Branchengehälter zu sein.","english":"In salary negotiations it is important to be well informed about industry salaries."},{"german":"Ich möchte mein Gehalt ansprechen — ich glaube, es entspricht nicht meiner Leistung.","english":"I would like to raise my salary — I believe it does not correspond to my performance."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss salary negotiations and use professional negotiation language in German."}}',
'{"items":[{"word":"das Branchengehalt","translation":"industry salary","pronunciation":"dahs BRAN-shen-geh-halt","example":"Branchengehalt recherchieren."},{"word":"ansprechen","translation":"to raise/address (a topic)","pronunciation":"AN-shprekh-en","example":"Ein Thema ansprechen."},{"word":"entsprechen","translation":"to correspond to/match","pronunciation":"ent-SHPREKH-en","example":"Der Leistung entsprechen."},{"word":"die Leistung","translation":"performance/achievement","pronunciation":"dee LYS-toong","example":"Gute Leistung zeigen."},{"word":"der Mindestlohn","translation":"minimum wage","pronunciation":"dayr MIN-dest-lohn","example":"Der Mindestlohn."},{"word":"die Gehaltserhöhung","translation":"pay rise","pronunciation":"dee geh-HALTS-er-hö-oong","example":"Gehaltserhöhung beantragen."}]}',
'{"title":"Entsprechen + dative — to correspond to, match","pattern":"etwas entspricht + dative (something corresponds to, matches, meets — dative)","explanation":"Entsprechen + dative = to correspond to, match, meet. Das Gehalt entspricht nicht meiner Leistung = The salary does not match my performance. Das entspricht meinen Erwartungen = That meets my expectations. Strong verb: entspricht / entsprach / hat entsprochen. Die Entsprechung = the correspondence, equivalent. Note: important that it takes DATIVE, not accusative. Common in formal language: den Anforderungen entsprechen = to meet the requirements.","examples":[{"sentence":"Das Ergebnis entspricht den Erwartungen.","translation":"The result meets the expectations."},{"sentence":"Sein Verhalten entspricht nicht unserem Verhaltenskodex.","translation":"His behaviour does not correspond to our code of conduct."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Leistung'' means?","options":["performance/achievement","work","contribution","output"],"correctAnswer":"performance/achievement"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In salary negotiations it is important to be well informed about industry salaries.","options":["Bei Gehaltsverhandlungen ist es wichtig, gut informiert über Branchengehälter zu sein.","Man sollte sein Gehalt kennen.","Informiere dich über Gehälter.","Gehaltsverhandlungen sind wichtig."],"correctAnswer":"Bei Gehaltsverhandlungen ist es wichtig, gut informiert über Branchengehälter zu sein."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Ergebnis entspricht den ___.","options":["Erwartungen","Erwartung","Erwarteten","erwarteten Zahlen"],"correctAnswer":"Erwartungen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: His behaviour does not correspond to our code of conduct","wordBankItems":["Sein","Verhalten","entspricht","nicht","unserem","Verhaltenskodex","."],"correctAnswer":"Sein Verhalten entspricht nicht unserem Verhaltenskodex ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Entsprechen'' takes which case?","options":["dative","accusative","genitive","nominative"],"correctAnswer":"dative"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000162',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss work contracts","Use Arbeitsvertrag vocabulary","Understand German employment law basics"],"explanation":{"intro":"Employment contract vocabulary at B1 covers the key terms and structure of German work contracts.","culturalNote":"In Germany, Arbeitsverträge (employment contracts) can be unbefristet (permanent) or befristet (fixed-term). The Probezeit (probationary period — typically 6 months) allows easier termination. The Kündigungsfrist (notice period) depends on contract terms. Nebentätigkeit (secondary employment) must often be disclosed. Tarifvertraglich gebundene Arbeitgeber must follow union agreements."},"examples":[{"german":"Vor der Unterschrift eines Arbeitsvertrags sollte man alle Klauseln sorgfältig prüfen.","english":"Before signing an employment contract one should carefully check all clauses."},{"german":"Ein unbefristeter Vertrag bietet mehr Sicherheit als ein befristeter.","english":"A permanent contract offers more security than a fixed-term one."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss employment contracts, key terms, and German labour law basics."}}',
'{"items":[{"word":"sorgfältig","translation":"carefully/thoroughly","pronunciation":"ZORG-fäl-tikh","example":"Sorgfältig prüfen."},{"word":"die Klausel","translation":"clause","pronunciation":"dee KLOW-zel","example":"Eine Klausel."},{"word":"unbefristet","translation":"permanent/open-ended","pronunciation":"OON-beh-fris-tet","example":"Unbefristeter Vertrag."},{"word":"befristet","translation":"fixed-term","pronunciation":"beh-FRIS-tet","example":"Befristeter Vertrag."},{"word":"die Probezeit","translation":"probationary period","pronunciation":"dee PRO-beh-tsyt","example":"Die Probezeit."},{"word":"die Kündigungsfrist","translation":"notice period","pronunciation":"dee KÜN-dee-goongs-frist","example":"Kündigungsfrist einhalten."}]}',
'{"title":"Vor der Unterschrift — before signing (temporal preposition + gerundive noun)","pattern":"vor + dative + noun (before + event/action)","explanation":"Vor + dative = before (temporal). Vor der Unterschrift = before the signature/signing (noun from unterschreiben → die Unterschrift). Vor der Entscheidung = before the decision. German often uses dative nouns after vor for temporal expressions. Compare: bevor + clause (before — as a conjunction): Bevor du unterschreibst = Before you sign. Both are correct; vor + noun is more concise in formal writing.","examples":[{"sentence":"Vor dem Kauf sollte man das Produkt testen.","translation":"Before the purchase one should test the product."},{"sentence":"Vor der Reise muss ich noch packen.","translation":"Before the trip I still need to pack."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Probezeit'' means?","options":["probationary period","trial time","test period","evaluation phase"],"correctAnswer":"probationary period"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Before signing an employment contract one should carefully check all clauses.","options":["Vor der Unterschrift eines Arbeitsvertrags sollte man alle Klauseln sorgfältig prüfen.","Verträge sollte man lesen.","Alle Klauseln verstehen ist wichtig.","Bevor man unterschreibt, prüft man den Vertrag."],"correctAnswer":"Vor der Unterschrift eines Arbeitsvertrags sollte man alle Klauseln sorgfältig prüfen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Vor dem Kauf sollte man das Produkt ___.","options":["testen","getestet","zu testen","testend"],"correctAnswer":"testen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Before the trip I still need to pack","wordBankItems":["Vor","der","Reise","muss","ich","noch","packen","."],"correctAnswer":"Vor der Reise muss ich noch packen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Unbefristet'' means?","options":["permanent/open-ended","indefinite","unlimited","without term"],"correctAnswer":"permanent/open-ended"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000163',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss dismissal law","Use Kündigungsrecht vocabulary","Understand German labour protection"],"explanation":{"intro":"Dismissal law vocabulary at B1 covers the legal protection against unfair dismissal in Germany.","culturalNote":"Germany has strong Kündigungsschutz (dismissal protection). After 6 months in a company with more than 10 employees, the Kündigungsschutzgesetz (KSchG) applies. Dismissals must be sozial gerechtfertigt (socially justified) — betriebsbedingt (operational), personenbedingt (personal), or verhaltensbedingt (misconduct). The Betriebsrat (works council) must be consulted. Abfindung (severance pay) is common in negotiated departures."},"examples":[{"german":"In Deutschland genießen Arbeitnehmer nach der Probezeit einen starken Kündigungsschutz.","english":"In Germany, employees enjoy strong dismissal protection after the probationary period."},{"german":"Eine fristlose Kündigung ist nur bei schwerwiegenden Vergehen möglich.","english":"Summary dismissal is only possible in cases of serious misconduct."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss German dismissal law, labour protection, and employment rights."}}',
'{"items":[{"word":"der Kündigungsschutz","translation":"dismissal protection","pronunciation":"dayr KÜN-dee-goongs-shoots","example":"Kündigungsschutz genießen."},{"word":"genießen","translation":"to enjoy (a right/status)","pronunciation":"geh-NEES-en","example":"Schutz genießen."},{"word":"fristlos","translation":"summary/without notice","pronunciation":"FRIST-lohs","example":"Fristlose Kündigung."},{"word":"schwerwiegend","translation":"serious/grave","pronunciation":"SHVER-vee-gend","example":"Schwerwiegende Vergehen."},{"word":"die Abfindung","translation":"severance pay","pronunciation":"dee AP-fin-doong","example":"Abfindung erhalten."},{"word":"sozial gerechtfertigt","translation":"socially justified","pronunciation":"zo-tsee-AHL geh-rekht-fer-tikht","example":"Sozial gerechtfertigte Kündigung."}]}',
'{"title":"Nur bei — only in cases of (restrictive condition)","pattern":"etwas ist nur bei + dative möglich (something is only possible in cases of, only when)","explanation":"Nur bei + dative = only in the case of, only when (restricted to specific conditions). Eine fristlose Kündigung ist nur bei schwerwiegenden Vergehen möglich = Summary dismissal is only possible in cases of serious misconduct. Bei here = in the case of, with (dative — circumstances). Pattern is common in legal/conditional language: nur bei Vorlage eines Ausweises = only upon presentation of an ID.","examples":[{"sentence":"Das Medikament ist nur bei ärztlicher Verschreibung erhältlich.","translation":"The medication is only available with a doctor''s prescription."},{"sentence":"Rückgaben sind nur bei unbeschädigter Ware möglich.","translation":"Returns are only possible with undamaged goods."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Abfindung'' means?","options":["severance pay","settlement","payout","redundancy pay"],"correctAnswer":"severance pay"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In Germany, employees enjoy strong dismissal protection after the probationary period.","options":["In Deutschland genießen Arbeitnehmer nach der Probezeit einen starken Kündigungsschutz.","Arbeitnehmer in Deutschland haben Rechte.","Nach der Probezeit kann man nicht so einfach gekündigt werden.","Kündigungsschutz ist in Deutschland wichtig."],"correctAnswer":"In Deutschland genießen Arbeitnehmer nach der Probezeit einen starken Kündigungsschutz."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Medikament ist nur bei ärztlicher Verschreibung ___.","options":["erhältlich","erhältend","zu erhalten","bekommt"],"correctAnswer":"erhältlich"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Returns are only possible with undamaged goods","wordBankItems":["Rückgaben","sind","nur","bei","unbeschädigter","Ware","möglich","."],"correctAnswer":"Rückgaben sind nur bei unbeschädigter Ware möglich ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Genießen'' in labour law context means?","options":["to enjoy (a right/status)","to benefit from","to have","to possess"],"correctAnswer":"to enjoy (a right/status)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000164',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss social insurance","Use Sozialversicherung vocabulary","Understand the German welfare state"],"explanation":{"intro":"Social insurance vocabulary at B1 covers Germany''s comprehensive social security system.","culturalNote":"Germany''s Sozialversicherungssystem is one of the world''s most comprehensive. The five pillars are: Krankenversicherung (health), Pflegeversicherung (long-term care), Rentenversicherung (pension), Unfallversicherung (accident), Arbeitslosenversicherung (unemployment). Contributions are shared between employer and employee (paritätisch). The system is Bismarck''s legacy (introduced 1883)."},"examples":[{"german":"Das deutsche Sozialversicherungssystem schützt Arbeitnehmer gegen die finanziellen Folgen von Krankheit und Alter.","english":"The German social insurance system protects employees against the financial consequences of illness and old age."},{"german":"Beiträge werden je zur Hälfte vom Arbeitgeber und vom Arbeitnehmer getragen.","english":"Contributions are borne equally by employer and employee."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss the German social insurance system and welfare state vocabulary."}}',
'{"items":[{"word":"der Beitrag","translation":"contribution","pronunciation":"dayr BY-trahg","example":"Beiträge zahlen."},{"word":"tragen","translation":"to bear/carry (costs)","pronunciation":"TRAH-gen","example":"Kosten tragen."},{"word":"je zur Hälfte","translation":"each half, equally","pronunciation":"yeh tsoor HEL-fteh","example":"Je zur Hälfte."},{"word":"die Pflegeversicherung","translation":"long-term care insurance","pronunciation":"dee PFLAY-geh-fer-zikh-eh-roong","example":"Pflegeversicherung."},{"word":"die Folge","translation":"consequence/result","pronunciation":"dee FOL-geh","example":"Finanzielle Folgen."},{"word":"schützen gegen","translation":"to protect against","pronunciation":"SHÜT-sen GAY-gen","example":"Schützen gegen Krankheit."}]}',
'{"title":"Schützen gegen — to protect against","pattern":"etwas/jemanden schützen gegen + accusative (to protect against)","explanation":"Schützen gegen + accusative = to protect against. Das System schützt Arbeitnehmer gegen Armut = The system protects employees against poverty. Also: schützen vor + dative (often interchangeable): schützen vor Krankheit = protect against/from illness. In practice: vor is more common for general protection; gegen often implies an active opposing force.","examples":[{"sentence":"Sonnencreme schützt die Haut gegen Sonnenbrand.","translation":"Sunscreen protects the skin against sunburn."},{"sentence":"Die Impfung schützt gegen gefährliche Krankheiten.","translation":"The vaccine protects against dangerous diseases."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Folge'' means?","options":["consequence/result","sequence","result","outcome"],"correctAnswer":"consequence/result"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The German social insurance system protects employees against the financial consequences of illness and old age.","options":["Das deutsche Sozialversicherungssystem schützt Arbeitnehmer gegen die finanziellen Folgen von Krankheit und Alter.","Das Sozialsystem ist gut in Deutschland.","Arbeitnehmer werden versichert.","Krankenversicherung schützt vor Kosten."],"correctAnswer":"Das deutsche Sozialversicherungssystem schützt Arbeitnehmer gegen die finanziellen Folgen von Krankheit und Alter."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Impfung schützt gegen gefährliche ___.","options":["Krankheiten","Krankheit","Erkrankungen","Infektionen"],"correctAnswer":"Krankheiten"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Sunscreen protects the skin against sunburn","wordBankItems":["Sonnencreme","schützt","die","Haut","gegen","Sonnenbrand","."],"correctAnswer":"Sonnencreme schützt die Haut gegen Sonnenbrand ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Tragen'' in costs context means?","options":["to bear/carry (costs)","to pay","to cover","to shoulder"],"correctAnswer":"to bear/carry (costs)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000165',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the pension system","Use Rente vocabulary","Talk about ageing and retirement"],"explanation":{"intro":"Pension vocabulary at B1 covers the German state pension, demographic challenges, and retirement planning.","culturalNote":"Germany''s gesetzliche Rentenversicherung (statutory pension insurance) is under pressure from demografischer Wandel (demographic change). Renteneintrittsalter (retirement age) was raised to 67. The Rentenlücke (pension gap — shortfall) is a major concern. Betriebliche Altersvorsorge (occupational pension) and private Altersvorsorge (Riester-Rente) supplement the state pension."},"examples":[{"german":"Der demografische Wandel stellt das Rentensystem vor erhebliche Herausforderungen.","english":"Demographic change poses considerable challenges for the pension system."},{"german":"Das Renteneintrittsalter wurde schrittweise auf 67 Jahre angehoben.","english":"The retirement age was gradually raised to 67 years."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss the German pension system, demographics, and retirement planning in German."}}',
'{"items":[{"word":"der demografische Wandel","translation":"demographic change","pronunciation":"dayr deh-mo-GRA-fee-sheh VAN-del","example":"Demografischer Wandel."},{"word":"schrittweise","translation":"gradually/step by step","pronunciation":"SHRIT-vy-zeh","example":"Schrittweise anheben."},{"word":"anheben","translation":"to raise/increase","pronunciation":"AN-hay-ben","example":"Das Rentenalter anheben."},{"word":"die Rentenlücke","translation":"pension gap","pronunciation":"dee REN-ten-lük-eh","example":"Die Rentenlücke schließen."},{"word":"vor Herausforderungen stehen","translation":"to face challenges","pronunciation":"for her-OWS-for-der-oon-gen shtay-en","example":"Vor Herausforderungen stehen."},{"word":"das Renteneintrittsalter","translation":"retirement age","pronunciation":"dahs REN-ten-yn-tris-al-ter","example":"Das Renteneintrittsalter."}]}',
'{"title":"Schrittweise — gradually, step by step","pattern":"schrittweise + verb (to do something gradually, in steps, incrementally)","explanation":"Schrittweise = step by step, gradually, incrementally (from Schritt = step). Das Rentenalter wurde schrittweise angehoben = The retirement age was gradually raised. Schrittweise vorgehen = to proceed step by step. Compare: allmählich (gradually — time-based, natural process), sukzessive (successively — more formal), nach und nach (little by little — more colloquial). Schrittweise implies deliberate, planned stages.","examples":[{"sentence":"Das System wird schrittweise modernisiert.","translation":"The system is being modernised step by step."},{"sentence":"Sie hat schrittweise mehr Verantwortung übernommen.","translation":"She gradually took on more responsibility."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Rentenlücke'' means?","options":["pension gap","pension shortfall","retirement gap","pension deficit"],"correctAnswer":"pension gap"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Demographic change poses considerable challenges for the pension system.","options":["Der demografische Wandel stellt das Rentensystem vor erhebliche Herausforderungen.","Das Rentensystem ist in Gefahr.","Weniger Junge zahlen für mehr Alte.","Demographische Probleme betreffen die Rente."],"correctAnswer":"Der demografische Wandel stellt das Rentensystem vor erhebliche Herausforderungen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das System wird schrittweise ___.","options":["modernisiert","modernisiert werden","modernisieren","modernisierend"],"correctAnswer":"modernisiert"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: She gradually took on more responsibility","wordBankItems":["Sie","hat","schrittweise","mehr","Verantwortung","übernommen","."],"correctAnswer":"Sie hat schrittweise mehr Verantwortung übernommen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Anheben'' means?","options":["to raise/increase","to lift","to heighten","to elevate"],"correctAnswer":"to raise/increase"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000166',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the housing market","Use Wohnungsmarkt vocabulary","Talk about rent and property in Germany"],"explanation":{"intro":"Advanced housing market vocabulary at B1 covers rents, property values, and housing policy.","culturalNote":"Germany has one of the lowest home ownership rates in Europe (~50%) — many Germans rent. Mietpreisbremse (rent brake — legislation limiting rent increases) was introduced in 2015. Wohnknappheit (housing shortage) in cities like Munich, Berlin, and Hamburg is severe. Gentrifizierung (gentrification) displaces poorer residents. Bauprojekte (construction projects) are frequently contested."},"examples":[{"german":"In Großstädten übersteigen die Mietpreise häufig die finanzielle Belastbarkeit von Durchschnittsverdienern.","english":"In major cities, rents frequently exceed the financial capacity of average earners."},{"german":"Die Mietpreisbremse soll verhindern, dass Mieten in begehrten Lagen unkontrolliert steigen.","english":"The rent brake is intended to prevent rents in sought-after locations from rising uncontrollably."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss the German housing market, rental law, and housing policy."}}',
'{"items":[{"word":"übersteigen","translation":"to exceed","pronunciation":"ü-ber-SHTY-gen","example":"Mieten übersteigen."},{"word":"die Belastbarkeit","translation":"capacity/resilience (financial)","pronunciation":"dee beh-LAST-bar-kyt","example":"Finanzielle Belastbarkeit."},{"word":"begehrt","translation":"sought-after/in demand","pronunciation":"beh-GAYRT","example":"Begehrte Lage."},{"word":"die Lage","translation":"location/situation","pronunciation":"dee LAH-geh","example":"Zentrale Lage."},{"word":"die Mietpreisbremse","translation":"rent brake","pronunciation":"dee MEET-prys-brem-zeh","example":"Mietpreisbremse."},{"word":"die Gentrifizierung","translation":"gentrification","pronunciation":"dee gen-tri-fee-TSEE-roong","example":"Gentrifizierung stoppen."}]}',
'{"title":"Übersteigen — to exceed (formal/analytical)","pattern":"etwas übersteigt etwas (something exceeds something — surpasses a limit or threshold)","explanation":"Übersteigen (strong) = to exceed, surpass, go beyond. Die Kosten übersteigen das Budget = The costs exceed the budget. Strong verb: übersteigt / überstieg / hat überstiegen. Compare: überschreiten (to cross over a limit — also common: das Budget überschreiten), übersteigen (exceeds in size/degree). Both are interchangeable in many contexts; übersteigen often for abstract comparisons, überschreiten for physical/spatial limits.","examples":[{"sentence":"Das Angebot übersteigt die Nachfrage um das Dreifache.","translation":"Supply exceeds demand by a factor of three."},{"sentence":"Sein Talent übersteigt bei weitem das seiner Mitbewerber.","translation":"His talent far exceeds that of his competitors."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Begehrt'' means?","options":["sought-after/in demand","desired","popular","fashionable"],"correctAnswer":"sought-after/in demand"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In major cities, rents frequently exceed the financial capacity of average earners.","options":["In Großstädten übersteigen die Mietpreise häufig die finanzielle Belastbarkeit von Durchschnittsverdienern.","In Städten sind Mieten hoch.","Viele können sich keine Wohnung leisten.","Die Mietpreise steigen in Großstädten."],"correctAnswer":"In Großstädten übersteigen die Mietpreise häufig die finanzielle Belastbarkeit von Durchschnittsverdienern."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Angebot übersteigt die Nachfrage um das ___.","options":["Dreifache","Dreimal","Dreifachen","Dreifach"],"correctAnswer":"Dreifache"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: His talent far exceeds that of his competitors","wordBankItems":["Sein","Talent","übersteigt","bei","weitem","das","seiner","Mitbewerber","."],"correctAnswer":"Sein Talent übersteigt bei weitem das seiner Mitbewerber ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Mietpreisbremse'' means?","options":["rent brake","rental ceiling","rent control","price limit for rents"],"correctAnswer":"rent brake"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000167',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss rental law","Use Mietrecht vocabulary","Understand tenant rights in Germany"],"explanation":{"intro":"Rental law vocabulary at B1 covers tenant rights, rental agreements, and disputes in German.","culturalNote":"Germany has very strong Mieterschutz (tenant protection). The Mieterverein (tenant association) offers legal advice. Nebenkostenabrechnung (utility cost settlement — often contentious) arrives annually. Kautionsrückgabe (deposit return — max 3 months'' cold rent) is regulated. Eigenbedarfskündigung (landlord requiring the property for own use) is a common and contested reason for eviction."},"examples":[{"german":"Mieterinnen und Mieter in Deutschland genießen einen vergleichsweise starken rechtlichen Schutz.","english":"Tenants in Germany enjoy comparatively strong legal protection."},{"german":"Die Nebenkosten müssen jährlich abgerechnet und dem Mieter offengelegt werden.","english":"Ancillary costs must be settled annually and disclosed to the tenant."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss rental law, tenant rights, and rental disputes in German."}}',
'{"items":[{"word":"vergleichsweise","translation":"comparatively/relatively","pronunciation":"fer-GLYKHS-vy-zeh","example":"Vergleichsweise günstig."},{"word":"die Nebenkosten","translation":"ancillary/additional costs","pronunciation":"dee NAY-ben-kos-ten","example":"Nebenkosten zahlen."},{"word":"abrechnen","translation":"to settle/account for","pronunciation":"AP-rekh-nen","example":"Kosten abrechnen."},{"word":"offenlegen","translation":"to disclose/reveal","pronunciation":"OF-en-lay-gen","example":"Informationen offenlegen."},{"word":"der Mieterverein","translation":"tenant association","pronunciation":"dayr MEE-ter-fer-yn","example":"Mieterverein beitreten."},{"word":"die Kaution","translation":"deposit","pronunciation":"dee kow-tsee-OHN","example":"Kaution hinterlegen."}]}',
'{"title":"Vergleichsweise — comparatively, relatively","pattern":"vergleichsweise + adjective/adverb (comparatively — in comparison to similar cases)","explanation":"Vergleichsweise = comparatively, in comparison (formal adverb). Vergleichsweise niedrig = comparatively low. Often used when making implicit cross-comparisons: Der Mieterschutz ist vergleichsweise stark = Tenant protection is comparatively strong (compared to other countries). Synonym: verhältnismäßig (proportionally — slightly different nuance — appropriate to circumstances); relativ (relative — more neutral). All three are formal and analytical.","examples":[{"sentence":"Das Gehalt ist vergleichsweise gut für diese Branche.","translation":"The salary is comparatively good for this sector."},{"sentence":"Die Qualität ist vergleichsweise hoch, aber der Preis auch.","translation":"The quality is comparatively high, but so is the price."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Kaution'' means?","options":["deposit","guarantee","security","down payment"],"correctAnswer":"deposit"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Tenants in Germany enjoy comparatively strong legal protection.","options":["Mieterinnen und Mieter in Deutschland genießen einen vergleichsweise starken rechtlichen Schutz.","Mieterschutz ist stark in Deutschland.","Deutschland schützt Mieter gut.","Mieter haben in Deutschland viele Rechte."],"correctAnswer":"Mieterinnen und Mieter in Deutschland genießen einen vergleichsweise starken rechtlichen Schutz."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Gehalt ist vergleichsweise gut für diese ___.","options":["Branche","Branchenbereich","Abteilung","Stelle"],"correctAnswer":"Branche"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The quality is comparatively high but so is the price","wordBankItems":["Die","Qualität","ist","vergleichsweise","hoch",",","aber","der","Preis","auch","."],"correctAnswer":"Die Qualität ist vergleichsweise hoch , aber der Preis auch ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Nebenkosten'' means?","options":["ancillary/additional costs","running costs","side costs","extra charges"],"correctAnswer":"ancillary/additional costs"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000168',1,'APPROVED','PUBLISHED',
'{"objectives":["Celebrate B1 completion","Review B1 achievements","Prepare for B2 level"],"explanation":{"intro":"Congratulations — you have reached the end of B1! This milestone lesson celebrates your achievement and prepares you for B2.","culturalNote":"Reaching B1 means you can understand the main points of clear standard input on familiar matters. At B1 you can handle most situations likely to arise while travelling in a German-speaking area and describe experiences, events, dreams, and ambitions. B2 (upper intermediate) will take you to independent, nuanced expression. Sie schaffen das — you can do it!"},"examples":[{"german":"Sie haben das B1-Niveau erreicht — das ist eine bedeutende Leistung auf dem Weg zur Zweisprachigkeit.","english":"You have reached B1 level — that is a significant achievement on the path to bilingualism."},{"german":"Mit B1 können Sie sich in den meisten Alltagssituationen auf Deutsch behelfen.","english":"With B1 you can manage in most everyday situations in German."}],"rewards":{"xp":200,"coins":100},"metadata":{"estimatedMinutes":15,"canDo":"I have completed B1 and I am ready to begin B2 — upper intermediate German!"}}',
'{"items":[{"word":"erreichen","translation":"to reach/achieve","pronunciation":"er-RY-khen","example":"Ein Ziel erreichen."},{"word":"bedeutend","translation":"significant/notable","pronunciation":"beh-DOY-tend","example":"Bedeutende Leistung."},{"word":"die Zweisprachigkeit","translation":"bilingualism","pronunciation":"dee TSVY-shprakh-ikh-kyt","example":"Zweisprachigkeit anstreben."},{"word":"sich behelfen mit","translation":"to manage/make do with","pronunciation":"zikh beh-HEL-fen mit","example":"Sich mit wenig behelfen."},{"word":"anstreben","translation":"to strive for/aim for","pronunciation":"AN-shtray-ben","example":"Ziele anstreben."},{"word":"der Meilenstein","translation":"milestone","pronunciation":"dayr MY-len-shtyn","example":"Einen Meilenstein erreichen."}]}',
'{"title":"B1 erreicht — reaching a milestone in German","pattern":"etwas erreichen (to reach, achieve — a goal, level, milestone)","explanation":"Erreichen = to reach, achieve, attain. Das Ziel erreichen = to reach the goal. Das B1-Niveau erreichen = to reach B1 level. Passive: Das Niveau wurde erreicht = The level was reached. Related: erzielen (to achieve — typically results/scores), schaffen (to manage/achieve — colloquial: Ich habe es geschafft = I did it/I achieved it!). The difference: erreichen (reach a destination), erzielen (produce a score), schaffen (overcome an obstacle).","examples":[{"sentence":"Sie hat ihr Ziel erreicht und ist jetzt sehr glücklich.","translation":"She has reached her goal and is now very happy."},{"sentence":"Ich habe es geschafft! Das B1 ist abgeschlossen.","translation":"I did it! B1 is completed."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Zweisprachigkeit'' means?","options":["bilingualism","multilingualism","two-language ability","dual language skill"],"correctAnswer":"bilingualism"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"You have reached B1 level — that is a significant achievement on the path to bilingualism.","options":["Sie haben das B1-Niveau erreicht — das ist eine bedeutende Leistung auf dem Weg zur Zweisprachigkeit.","B1 ist ein wichtiges Niveau.","Das Erreichen von B1 ist toll.","Mit B1 kann man Deutsch."],"correctAnswer":"Sie haben das B1-Niveau erreicht — das ist eine bedeutende Leistung auf dem Weg zur Zweisprachigkeit."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich habe es ___! Das B1 ist abgeschlossen.","options":["geschafft","erreicht","getan","gemacht"],"correctAnswer":"geschafft"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: She has reached her goal and is now very happy","wordBankItems":["Sie","hat","ihr","Ziel","erreicht","und","ist","jetzt","sehr","glücklich","."],"correctAnswer":"Sie hat ihr Ziel erreicht und ist jetzt sehr glücklich ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Bedeutend'' means?","options":["significant/notable","big","important","major"],"correctAnswer":"significant/notable"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

